'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { KeyIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { CreateSlot } from './create-key';
import { IDLE_AFTER_DAYS, WORKSPACE_NAME, type ApiKey } from './data';
import { KeyList, MONEY_FORMAT } from './key-rows';
import {
  CREATE_MS,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
} from './session';
import { SettingsFrame, SettingsSection, SURFACE } from './settings-frame';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function totalSpendOf(keys: ApiKey[]) {
  let cents = 0;
  for (const key of keys) {
    cents += key.spendCents;
  }
  return cents / 100;
}

function keysWordOf(count: number) {
  if (count === 1) {
    return 'key';
  }
  return 'keys';
}

/** The fill of a held Revoke belongs to the demonstration only while it plays. */
function demoHoldOf(isAutoplaying: boolean, holdingId: string | null) {
  if (isAutoplaying) {
    return holdingId;
  }
  return null;
}

/** A revoked row takes its button with it: the focus goes to the row after it, or before it. */
function focusAfterRevokeOf(keys: ApiKey[], id: string) {
  const index = keys.findIndex((key) => key.id === id);
  const neighbour = keys[index + 1] ?? keys[index - 1];
  if (neighbour) {
    return `[data-row-toggle="${neighbour.id}"]`;
  }
  return '[data-create-key]';
}

function EmptyKeys() {
  return (
    <div className='flex flex-col items-center gap-2 px-4 py-10 text-center'>
      <span className='keycap-3d text-muted-foreground flex size-10 items-center justify-center rounded-lg'>
        <KeyIcon className='size-5' />
      </span>
      <p className='text-[13px] font-medium'>No API keys</p>
      <p className='text-muted-foreground max-w-xs text-xs text-pretty'>
        Create a key to call the Tidewell API from your own servers
      </p>
    </div>
  );
}

export default function Settings04() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const count = state.keys.length;
  const isEmpty = count === 0;
  const isSlotClosed = state.status === 'closed';
  const showsEmpty = isEmpty && isSlotClosed;
  const totalSpend = totalSpendOf(state.keys);
  const demoHoldingId = demoHoldOf(isAutoplaying, state.holdingId);
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function openCreate() {
    act({ type: 'createOpened' });
    focusLater('[data-key-name]');
  }

  function closeCreate() {
    const isEditing = state.status === 'editing';
    if (!isEditing) {
      return;
    }
    act({ type: 'createClosed' });
    focusLater('[data-create-key]');
  }

  function revealCreated() {
    act({ type: 'keyCreated' });
    focusLater('[data-secret-copy]');
  }

  function submit() {
    const after = reducer(state, { type: 'createSubmitted' });
    act({ type: 'createSubmitted' });
    if (after.status !== 'creating') {
      focusLater('[data-key-name]');
      return;
    }
    schedule(revealCreated, CREATE_MS);
  }

  async function copy() {
    const value = state.secret?.value;
    if (!value) {
      return;
    }
    try {
      await navigator.clipboard.writeText(value);
    } catch {
      act({ type: 'copyFailed' });
      return;
    }
    act({ type: 'secretCopied' });
  }

  function hide() {
    const keyId = state.secret?.keyId;
    act({ type: 'secretHidden' });
    if (keyId) {
      focusLater(`[data-row-toggle="${keyId}"]`);
    }
  }

  function toggle(id: string) {
    act({ type: 'rowToggled', id });
  }

  function revoke(id: string) {
    const target = focusAfterRevokeOf(state.keys, id);
    act({ type: 'revoked', id });
    focusLater(target);
  }

  /** A key on its way belongs to the round it was asked for in. */
  function replay() {
    clearAll();
    restart();
  }

  const createButton = (
    <Button
      type='button'
      data-create-key
      disabled={!isSlotClosed}
      focusableWhenDisabled
      onClick={openCreate}
      className={pressedSolidOf(pressed === 'create')}
    >
      <PlusIcon />
      Create key
    </Button>
  );

  const replayButton = (
    <ReplayButton isShown={canReplay} onReplay={replay} label='Replay' />
  );

  return (
    <ClockGate isActive={isInView}>
      <SettingsFrame
        ref={ref}
        title='API keys'
        line={`Keys let your own servers call the Tidewell API for ${WORKSPACE_NAME}. Each one reaches only what its access allows.`}
        aside={replayButton}
      >
        <SettingsSection
          title='Keys'
          line={
            <span className='flex flex-wrap items-center gap-x-1.5 gap-y-1 tabular-nums'>
              <span>
                <MotionNumber value={count} /> {keysWordOf(count)}
              </span>
              <span aria-hidden='true'>·</span>
              <span>
                <MotionNumber value={totalSpend} format={MONEY_FORMAT} /> this
                month
              </span>
              <Badge variant='secondary'>Illustrative</Badge>
            </span>
          }
          action={createButton}
        >
          <div className={cn(SURFACE, 'overflow-hidden')}>
            <CreateSlot
              state={state}
              pressed={pressed}
              onAction={act}
              onSubmit={submit}
              onClose={closeCreate}
              onCopy={copy}
              onHide={hide}
            />
            <KeyList
              keys={state.keys}
              openId={state.openId}
              pressed={pressed}
              demoHoldingId={demoHoldingId}
              onToggle={toggle}
              onRevoke={revoke}
            />
            {showsEmpty && <EmptyKeys />}
          </div>
        </SettingsSection>
        <p className='text-muted-foreground text-xs text-pretty'>
          {`Keys that make no request for ${IDLE_AFTER_DAYS} days are flagged as idle. Revoking asks for a two-second hold, so it never happens by accident.`}
        </p>
        <LiveRegion message={message} />
      </SettingsFrame>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import {
  CheckIcon,
  CopyIcon,
  TriangleAlertIcon,
} from '@/registry/ndeko/lib/icons';
import { fadePresence } from '@/registry/ndeko/lib/motion-presets';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { Input } from '@/registry/ndeko/ui/input';
import { Label } from '@/registry/ndeko/ui/label';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';
import { Wash } from '@/registry/ndeko/ui/wash';

import {
  ACCESS_LABEL,
  ENVIRONMENT_LABEL,
  NAME_MAX_LENGTH,
  type Access,
  type Environment,
} from './data';
import type { CreateStatus, KeysAction, KeysState, Secret } from './session';
import { describedByOf, ErrorLine } from './settings-frame';

const ENVIRONMENTS: Segment<Environment>[] = [
  { value: 'live', label: ENVIRONMENT_LABEL.live },
  { value: 'test', label: ENVIRONMENT_LABEL.test },
];

const ACCESSES: Segment<Access>[] = [
  { value: 'full', label: ACCESS_LABEL.full },
  { value: 'read', label: ACCESS_LABEL.read },
];

const ENVIRONMENT_LINE: Record<Environment, string> = {
  live: 'Reaches your real data and is billed',
  test: 'Reaches a sandbox and costs nothing',
};

const CREATE_LABELS: Record<MorphState, string> = {
  idle: 'Create key',
  busy: 'Creating',
  done: 'Created',
};

function morphOf(status: CreateStatus): MorphState {
  if (status === 'creating') {
    return 'busy';
  }
  return 'idle';
}

function isFormStatus(status: CreateStatus) {
  const isEditing = status === 'editing';
  const isCreating = status === 'creating';
  return isEditing || isCreating;
}

function shownSecretOf(state: KeysState) {
  if (state.status !== 'revealed') {
    return null;
  }
  return state.secret;
}

function copyLabelOf(isCopied: boolean) {
  if (isCopied) {
    return 'Copied';
  }
  return 'Copy key';
}

type KeyFormProps = {
  state: KeysState;
  pressed: string | null;
  onAction: (action: KeysAction) => void;
  onSubmit: () => void;
  onClose: () => void;
};

function KeyForm({
  state,
  pressed,
  onAction,
  onSubmit,
  onClose,
}: KeyFormProps) {
  const nameId = useId();
  const errorId = useId();
  const draft = state.draft;
  const isCreating = state.status === 'creating';
  const hasError = state.nameError !== null;
  const environmentLine = ENVIRONMENT_LINE[draft.environment];

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit();
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLFormElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onClose();
  }

  return (
    <form
      noValidate
      onSubmit={submit}
      onKeyDown={closeOnEscape}
      className='bg-foreground/[0.025] flex flex-col gap-4 p-4'
    >
      <div className='flex flex-col gap-1.5'>
        <Label htmlFor={nameId}>Name</Label>
        <Input
          id={nameId}
          data-key-name
          value={draft.name}
          maxLength={NAME_MAX_LENGTH}
          autoComplete='off'
          spellCheck={false}
          placeholder='Where the key is used'
          readOnly={isCreating}
          aria-invalid={hasError}
          aria-describedby={describedByOf(hasError, errorId)}
          onChange={(event) =>
            onAction({ type: 'named', value: event.target.value })
          }
          className='@lg:max-w-80'
        />
        <ErrorLine
          id={errorId}
          error={state.nameError}
          attempts={state.attempts}
        />
      </div>
      <div className='flex flex-wrap gap-x-8 gap-y-4'>
        <div className='flex flex-col gap-1.5'>
          <span className='text-[13px] leading-none font-medium'>
            Environment
          </span>
          <Segments
            value={draft.environment}
            segments={ENVIRONMENTS}
            label='Environment'
            onValueChange={(environment) =>
              onAction({ type: 'environmentPicked', environment })
            }
            className='w-fit'
          />
          <span className='text-muted-foreground flex text-xs'>
            <Swap swapKey={draft.environment}>{environmentLine}</Swap>
          </span>
        </div>
        <div className='flex flex-col gap-1.5'>
          <span className='text-[13px] leading-none font-medium'>Access</span>
          <Segments
            value={draft.access}
            segments={ACCESSES}
            label='Access'
            onValueChange={(access) =>
              onAction({ type: 'accessPicked', access })
            }
            className='w-fit'
          />
        </div>
      </div>
      <div className='flex flex-wrap items-center justify-end gap-2'>
        <Button
          type='button'
          variant='ghost'
          disabled={isCreating}
          onClick={onClose}
        >
          Cancel
        </Button>
        <MorphButton
          type='submit'
          state={morphOf(state.status)}
          labels={CREATE_LABELS}
          className={pressedSolidOf(pressed === 'submit')}
        />
      </div>
    </form>
  );
}

type SecretPanelProps = {
  secret: Secret;
  pressed: string | null;
  onCopy: () => void;
  onHide: () => void;
};

/** Waits on the person until they hide it, so it wears the warning wash while it is there. */
function SecretPanel({ secret, pressed, onCopy, onHide }: SecretPanelProps) {
  const isCopied = secret.isCopied;
  const copyLabel = copyLabelOf(isCopied);

  return (
    <div className='relative isolate flex flex-col gap-3 p-4'>
      <Wash color='var(--warning)' />
      <p className='flex items-start gap-2 text-[13px] text-pretty'>
        <TriangleAlertIcon className='text-warning-foreground mt-0.5 size-4 shrink-0' />
        <span>
          <span className='font-medium'>{`Copy the key for ${secret.name} now.`}</span>{' '}
          It is shown once: after you hide it, only its last four characters
          stay.
        </span>
      </p>
      <div className='bg-foreground/[0.05] flex flex-wrap items-center gap-2 rounded-lg p-1.5 ps-3'>
        <code className='min-w-0 flex-1 basis-48 font-mono text-[13px] break-all select-all'>
          {secret.value}
        </code>
        <Button
          type='button'
          size='sm'
          data-secret-copy
          onClick={onCopy}
          className={pressedSolidOf(pressed === 'copy')}
        >
          <Swap swapKey={String(isCopied)}>
            {isCopied && <CheckIcon />}
            {!isCopied && <CopyIcon />}
          </Swap>
          <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
            <Swap swapKey={copyLabel}>{copyLabel}</Swap>
          </AnimatedSize>
        </Button>
      </div>
      <div className='flex flex-wrap items-center justify-between gap-x-4 gap-y-2'>
        <p className='text-muted-foreground text-xs'>
          A sample key: it opens nothing in this preview
        </p>
        <Button
          type='button'
          variant='outline'
          size='sm'
          onClick={onHide}
          className={pressedQuietOf(pressed === 'hide')}
        >
          Hide key
        </Button>
      </div>
    </div>
  );
}

type CreateSlotProps = {
  state: KeysState;
  pressed: string | null;
  onAction: (action: KeysAction) => void;
  onSubmit: () => void;
  onClose: () => void;
  onCopy: () => void;
  onHide: () => void;
};

/** The top of the card grows into the form, the form gives way to the secret, then it all folds away. */
export function CreateSlot({
  state,
  pressed,
  onAction,
  onSubmit,
  onClose,
  onCopy,
  onHide,
}: CreateSlotProps) {
  const fade = fadePresence();
  const isForm = isFormStatus(state.status);
  const secret = shownSecretOf(state);

  return (
    <AnimatedSize contentClassName='relative'>
      <AnimatePresence mode='popLayout' initial={false}>
        {isForm && (
          <motion.div key='form' {...fade}>
            <KeyForm
              state={state}
              pressed={pressed}
              onAction={onAction}
              onSubmit={onSubmit}
              onClose={onClose}
            />
          </motion.div>
        )}
        {secret && (
          <motion.div key='secret' {...fade}>
            <SecretPanel
              secret={secret}
              pressed={pressed}
              onCopy={onCopy}
              onHide={onHide}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </AnimatedSize>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import {
  ChevronDownIcon,
  HourglassIcon,
  KeyIcon,
} from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Chip } from '@/registry/ndeko/ui/chip';

import {
  ENVIRONMENT_LABEL,
  IDLE_AFTER_DAYS,
  SCOPES,
  type ApiKey,
  type Environment,
} from './data';
import { HoldButton } from './hold-button';
import { maskedKeyOf } from './session';

export const MONEY_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
};

const COUNT = new Intl.NumberFormat('en-US');

const ENVIRONMENT_COLOR: Record<Environment, string> = {
  live: 'var(--success)',
  test: 'var(--info)',
};

function isIdle(key: ApiKey) {
  if (key.idleDays === null) {
    return false;
  }
  return key.idleDays >= IDLE_AFTER_DAYS;
}

function controlsOf(isOpen: boolean, id: string) {
  if (isOpen) {
    return id;
  }
  return undefined;
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return undefined;
}

function totalOf(values: number[]) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

function requestsLineOf(total: number) {
  if (total === 1) {
    return '1 request';
  }
  return `${COUNT.format(total)} requests`;
}

/** A day without requests keeps a sliver, so the fourteen days stay countable. */
const LOWEST_BAR_PERCENT = 6;

const BAR_STAGGER_MS = 18;

/** Each bar grows from the floor when the row opens, a beat after the one before it. */
function barStyleOf(count: number, highest: number, index: number) {
  const share = count / highest;
  const sharePercent = share * 100;
  const percent = Math.max(sharePercent, LOWEST_BAR_PERCENT);
  const delay = index * BAR_STAGGER_MS;
  return { height: `${percent}%`, transitionDelay: `${delay}ms` };
}

function UsageBars({ requests }: { requests: number[] }) {
  const highest = Math.max(...requests);
  const total = totalOf(requests);
  const hasRequests = highest > 0;
  const summary = `${requestsLineOf(total)} over the last 14 days, ${COUNT.format(highest)} on the busiest day`;

  if (!hasRequests) {
    return (
      <p className='bg-foreground/[0.03] text-muted-foreground flex h-10 items-center justify-center rounded-md text-xs'>
        No requests in the last 14 days
      </p>
    );
  }

  return (
    <div role='img' aria-label={summary} className='flex h-10 items-end gap-1'>
      {requests.map((count, index) => (
        <span
          key={`day-${index}`}
          style={barStyleOf(count, highest, index)}
          className='bg-primary w-full max-w-4 origin-bottom scale-y-100 rounded-t-[3px] transition-[scale] duration-300 ease-(--ease-out-strong) starting:scale-y-0'
        />
      ))}
    </div>
  );
}

type KeyDetailsProps = {
  apiKey: ApiKey;
  isDemoHolding: boolean;
  onRevoke: (id: string) => void;
};

function KeyDetails({ apiKey, isDemoHolding, onRevoke }: KeyDetailsProps) {
  const scopes = SCOPES[apiKey.access];
  const total = totalOf(apiKey.requests);
  const showsIdleNote = isIdle(apiKey);

  return (
    <div className='flex flex-col gap-4 px-4 pt-1 pb-4 @xl:ps-[3.75rem]'>
      <dl className='grid gap-x-6 gap-y-3 @xl:grid-cols-2'>
        <div className='flex flex-col gap-1.5'>
          <dt className='text-muted-foreground text-xs'>Scopes</dt>
          <dd className='flex flex-wrap gap-1'>
            {scopes.map((scope) => (
              <Badge
                key={scope}
                variant='secondary'
                className='font-mono text-[11px] font-normal'
              >
                {scope}
              </Badge>
            ))}
          </dd>
        </div>
        <div className='flex flex-col gap-1.5'>
          <dt className='text-muted-foreground text-xs'>Created</dt>
          <dd className='flex min-w-0 items-center gap-2 text-[13px]'>
            <Avatar seed={apiKey.createdBy} className='size-5' />
            <span className='truncate'>
              {apiKey.createdBy}, {apiKey.createdOn}
            </span>
          </dd>
        </div>
      </dl>
      <div className='flex flex-col gap-2'>
        <p className='text-muted-foreground flex items-baseline justify-between gap-3 text-xs'>
          <span>Requests, last 14 days</span>
          <span className='tabular-nums'>{requestsLineOf(total)}</span>
        </p>
        <UsageBars requests={apiKey.requests} />
      </div>
      {showsIdleNote && (
        <p className='text-warning-foreground text-xs text-pretty'>
          {`No request since ${apiKey.lastUsed}. If nothing needs it any more, revoke it.`}
        </p>
      )}
      <div className='flex flex-wrap items-center justify-between gap-x-4 gap-y-2'>
        <p className='text-muted-foreground min-w-0 flex-1 basis-48 text-xs text-pretty'>
          Apps that use this key stop working at once
        </p>
        <HoldButton
          label='Hold to revoke'
          hint={`Press and hold for two seconds to revoke ${apiKey.name}`}
          isDemoHolding={isDemoHolding}
          onComplete={() => onRevoke(apiKey.id)}
        />
      </div>
    </div>
  );
}

type KeyRowProps = {
  apiKey: ApiKey;
  isOpen: boolean;
  isPressed: boolean;
  isDemoHolding: boolean;
  onToggle: (id: string) => void;
  onRevoke: (id: string) => void;
};

function KeyRow({
  apiKey,
  isOpen,
  isPressed,
  isDemoHolding,
  onToggle,
  onRevoke,
}: KeyRowProps) {
  const detailsId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const showsIdle = isIdle(apiKey);
  const spend = apiKey.spendCents / 100;
  const masked = maskedKeyOf(apiKey.environment, apiKey.tail);

  return (
    <div className='flex flex-col'>
      <button
        type='button'
        data-row-toggle={apiKey.id}
        aria-expanded={isOpen}
        aria-controls={controlsOf(isOpen, detailsId)}
        onClick={() => onToggle(apiKey.id)}
        className='hover:bg-foreground/[0.025] focus-visible:ring-ring/25 grid w-full cursor-pointer grid-cols-[auto_minmax(0,1fr)_auto] items-start gap-x-3 px-4 py-3 text-start transition-colors duration-150 outline-none focus-visible:ring-[3px] focus-visible:ring-inset'
      >
        <span className='keycap-3d text-muted-foreground flex size-8 items-center justify-center rounded-lg'>
          <KeyIcon className='size-4' />
        </span>
        <span className='flex min-w-0 flex-col gap-1'>
          <span className='flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1'>
            <span className='min-w-0 truncate text-[13px] font-medium'>
              {apiKey.name}
            </span>
            <Chip color={ENVIRONMENT_COLOR[apiKey.environment]}>
              {ENVIRONMENT_LABEL[apiKey.environment]}
            </Chip>
            {showsIdle && (
              <Badge variant='warning'>
                <HourglassIcon />
                {`Idle for ${apiKey.idleDays} days`}
              </Badge>
            )}
          </span>
          <span className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-0.5 text-xs'>
            <code className='font-mono'>{masked}</code>
            <span aria-hidden='true'>·</span>
            <span>Created {apiKey.createdOn}</span>
            <span aria-hidden='true'>·</span>
            <span>Last used {apiKey.lastUsed}</span>
          </span>
        </span>
